mapper.select:
SELECT product_id AS productId, MAX(product_name) AS productName, MAX(category_name) AS categoryName, MAX(brand) AS brand, SUM(gmv) AS gmv, SUM(sales_qty) AS salesQty, SUM(order_cnt) AS orderCnt FROM ads_product_stat WHERE 1 = 1
AND stat_date >= #{q.startDate}
AND stat_date <= #{q.endDate}
GROUP BY product_id ORDER BY gmv DESC
LIMIT #{q.limit}

SELECT stat_date AS statDate, order_cnt AS orderCnt, valid_order_cnt AS validOrderCnt, gmv AS gmv, sales_qty AS salesQty, buyer_cnt AS buyerCnt, avg_order_amount AS avgOrderAmount, refund_order_cnt AS refundOrderCnt, refund_rate AS refundRate FROM ads_daily_trend WHERE 1 = 1
AND stat_date >= #{q.startDate}
AND stat_date <= #{q.endDate}
ORDER BY stat_date

SELECT product_id AS productId, product_name AS productName, category_name AS categoryName, brand AS brand, SUM(pay_amount) AS gmv, SUM(quantity) AS salesQty, COUNT(DISTINCT order_id) AS orderCnt FROM dwd_order_detail WHERE 1 = 1
GROUP BY product_id, product_name, category_name, brand ORDER BY gmv DESC
LIMIT #{q.limit}
